model:
rachana: 1
sutra: lei-relationship
version: 1
description: 
match: { kind: lei-relationship, priority: 10 }
title: { pill: "GLEIF · Relationship", id: "$.RELATIONSHIP_ID", with: "$.LEVEL + ' parent'" }
strip:
  - { label: "Level", bind: "$.LEVEL + ' parent'", emphasis: true }
  - { label: "Status", bind: "$.RELATIONSHIP_STATUS", tone: "status" }
  - { label: "Since", bind: "$.START", fmt: "date" }
  - { label: "Accounting standard", bind: "$.ACCOUNTING_STANDARD" }
  - { label: "Record", bind: "$.REGISTRATION_STATUS == 'LAPSED' ? 'LAPSED: renewal failed' : $.REGISTRATION_STATUS", tone: "status" }
panels:
  - id: relationship
    kind: kv
    title: "The relationship"
    key: "F2"
    columns:
      - { label: "Child", bind: "link($.CHILD_ENTITY, 'lei-entity')" }
      - { label: "Is consolidated by", bind: "link($.PARENT_ENTITY, 'lei-entity')" }
      - { label: "Level", bind: "$.LEVEL + ' accounting consolidation parent'" }
      - { label: "Relationship status", bind: "$.RELATIONSHIP_STATUS" }
      - { label: "Relationship start", bind: "$.START", fmt: "date" }
      - { label: "Relationship end", bind: "nonblank($.END, 'Open')" }
      - { label: "Ownership group", bind: "link($.LEI_GROUP, 'lei-group')" }
  - id: periods
    kind: table
    title: "Accounting and filing periods the record names"
    rows: "$.PERIODS"
    when: "size($.PERIODS) > 0"
    search: false
    columns:
      - { label: "Period", bind: "@.TYPE" }
      - { label: "From", bind: "@.START", fmt: "date" }
      - { label: "To", bind: "nonblank(@.END, 'Open')" }
  - id: record
    kind: status
    title: "The relationship record"
    area: right
    fields: [{ label: "Registration status", bind: "$.REGISTRATION_STATUS == 'LAPSED' ? 'LAPSED: renewal failed' : $.REGISTRATION_STATUS", tone: "status" }, { label: "First registered", bind: "$.INITIAL_REGISTRATION", fmt: "date" }, { label: "Last updated", bind: "$.LAST_UPDATE", fmt: "date" }, { label: "Next renewal", bind: "$.NEXT_RENEWAL", fmt: "date" }]
  - id: child
    kind: kv
    title: "The child"
    area: right
    columns:
      - { label: "Legal name", bind: "link($src.LEI, 'lei-entity', $src.NAME)" }
      - { label: "LEI", bind: "$src.LEI" }
      - { label: "Legal form", bind: "$src.LEGAL_FORM" }
      - { label: "Category", bind: "nonblank($src.CATEGORY, 'General')" }
      - { label: "Jurisdiction", bind: "nonblank($src.JURISDICTION, $src.LEI_COUNTRY)" }
      - { label: "Country", bind: "link($src.LEI_COUNTRY, 'lei-country', $src.COUNTRY_NAME)" }
      - { label: "City", bind: "$src.LEGAL_CITY" }
      - { label: "Registered as", bind: "$src.REGISTERED_AS" }
      - { label: "Entity status", bind: "$src.ENTITY_STATUS" }
      - { label: "Registration", bind: "$src.REGISTRATION_STATUS == 'LAPSED' ? 'LAPSED: renewal failed' : $src.REGISTRATION_STATUS", tone: "status" }
      - { label: "Next renewal", bind: "$src.NEXT_RENEWAL", fmt: "date" }
      - { label: "Managing LOU", bind: "$src.MANAGING_LOU" }
      - { label: "Direct parent", bind: "link($src.DIRECT_PARENT, 'lei-entity')" }
      - { label: "Ownership group", bind: "link($src.LEI_GROUP, 'lei-group')" }
      - { label: "Children in the pack", bind: "$src.CHILD_COUNT", fmt: "entities0" }
      - { label: "BICs", bind: "$src.BICS" }
      - { label: "ISINs (GLEIF mapping)", bind: "$src.ISIN_COUNT", fmt: "entities0" }
  - id: parent-entity
    kind: kv
    title: "The parent"
    area: right
    columns:
      - { label: "Legal name", bind: "link($src.LEI, 'lei-entity', $src.NAME)" }
      - { label: "LEI", bind: "$src.LEI" }
      - { label: "Legal form", bind: "$src.LEGAL_FORM" }
      - { label: "Category", bind: "nonblank($src.CATEGORY, 'General')" }
      - { label: "Jurisdiction", bind: "nonblank($src.JURISDICTION, $src.LEI_COUNTRY)" }
      - { label: "Country", bind: "link($src.LEI_COUNTRY, 'lei-country', $src.COUNTRY_NAME)" }
      - { label: "City", bind: "$src.LEGAL_CITY" }
      - { label: "Registered as", bind: "$src.REGISTERED_AS" }
      - { label: "Entity status", bind: "$src.ENTITY_STATUS" }
      - { label: "Registration", bind: "$src.REGISTRATION_STATUS == 'LAPSED' ? 'LAPSED: renewal failed' : $src.REGISTRATION_STATUS", tone: "status" }
      - { label: "Next renewal", bind: "$src.NEXT_RENEWAL", fmt: "date" }
      - { label: "Managing LOU", bind: "$src.MANAGING_LOU" }
      - { label: "Direct parent", bind: "link($src.DIRECT_PARENT, 'lei-entity')" }
      - { label: "Ownership group", bind: "link($src.LEI_GROUP, 'lei-group')" }
      - { label: "Children in the pack", bind: "$src.CHILD_COUNT", fmt: "entities0" }
      - { label: "BICs", bind: "$src.BICS" }
      - { label: "ISINs (GLEIF mapping)", bind: "$src.ISIN_COUNT", fmt: "entities0" }
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
keys: { F5: "link($.CHILD_ENTITY, 'lei-entity', 'Child')", F6: "link($.PARENT_ENTITY, 'lei-entity', 'Parent')", F7: "link($.LEI_GROUP, 'lei-group', 'Ownership group')", F9: "raw" }
